<?php

namespace Database\Seeders;

use App\Models\BlogCategory;
use App\Models\BlogPost;
use Carbon\Carbon;
use Illuminate\Database\Seeder;

class BlogPostSeeder extends Seeder
{
    public function run(): void
    {
        if (BlogPost::count() > 0) {
            return;
        }

        $categoryIds = BlogCategory::pluck('id', 'slug')->all();

        // First post goes live on the next business day at 10:00
        $startDate = Carbon::now()->addWeekday()->setTime(10, 0, 0);

        $posts = array_merge(
            $this->weddingPosts($categoryIds),
            $this->baptismPosts($categoryIds),
            $this->promPosts($categoryIds),
            $this->behindPosts($categoryIds),
            $this->stylePosts($categoryIds),
        );

        foreach ($posts as $index => $data) {
            $publishedAt = $startDate->copy()->addWeekdays($index * 4);

            BlogPost::create(array_merge($data, [
                'is_published' => true,
                'published_at' => $publishedAt,
            ]));
        }
    }

    private function weddingPosts(array $cats): array
    {
        $catId = $cats['wedding-tips'] ?? null;
        $cover = 'css/img/Edited_IMG_9630.jpg';

        return [
            [
                'title' => 'Как да изберете сватбен фотограф във Варна - 7 ключови въпроса',
                'slug' => 'kak-da-izberete-svatben-fotograf-varna',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Изборът на сватбен фотограф е едно от най-важните решения при планиране на сватбата. Ето 7-те въпроса, които задължително трябва да зададете, преди да подпишете договор.',
                'meta_description' => '7 въпроса, които трябва да зададете на сватбения си фотограф във Варна преди да го наемете. Практичен гид от Take Two Studio.',
                'body' => '<p>Изборът на сватбен фотограф не е като наемане на коя да е услуга. Това е човекът, който ще документира един от най-важните дни в живота ви, и резултатът ще остане завинаги. В този гид споделяме 7-те въпроса, които задължително трябва да зададете на всеки фотограф, преди да вземете решение.</p><h2>1. Какъв опит имате със сватби?</h2><p>Има разлика между няколко заснети сватби и десетки. С опита идват увереност, предвиждане на ключовите моменти и способност за реакция при непредвидени ситуации. Опитните фотографи знаят кога ще се появи сълзата, кога булката ще погледне младоженеца и кога светлината ще стане златна. В Take Two Studio членовете на екипа имат над 10 години индивидуален опит, а студиото работи в този състав от 2019 година.</p><h2>2. Какъв е вашият стил на фотография?</h2><p>Репортажен, класически, fine art, светъл и въздушен, кинематографичен - всеки фотограф има собствен почерк. Поискайте да видите поне една пълна сватба от начало до край, а не само best-of колекция. Това ще ви даде реална представа какъв ще е албумът ви.</p><h2>3. Какво пише в договора?</h2><p>Професионалният фотограф винаги работи с договор. В него трябва ясно да са описани: часове покритие, брой фотографи, време за предаване на материалите, какво се случва при форсмажор, правата върху снимките и условията за отказ.</p><h2>4. Кога ще получим готовите снимки?</h2><p>При нас официалният срок за сватбен албум е до 60 работни дни. Качествената обработка на над хиляда кадъра отнема време, и това е норма в индустрията. Ако някой обещава готови снимки за седмица, внимавайте. Ако някой иска 6 месеца, също внимавайте.</p><h2>5. Какъв е резервният ви план?</h2><p>Какво се случва, ако фотографът се разболее в деня на сватбата? Има ли двойна екипировка? Работи ли със замяна? Това са въпроси, които никой не обича да задава, но които правят разликата между спокойствие и катастрофа.</p><h2>6. Какво точно включва цената?</h2><p>Цената не е единственият показател. Един пакет може да включва само фотограф и няколко часа, друг - пълно покритие с фотограф, оператор, дрон и албум. Винаги сравнявайте какво точно получавате, не само крайната сума. Нашите пакети са публикувани на страницата за сватби с ясно описание какво включва всеки вариант.</p><h2>7. Имаме ли химия?</h2><p>Най-подценяваният въпрос. Ще прекарате с този човек 8-12 часа в най-емоционалния ден от живота си. Ако още на първата среща ви е неудобно, това няма да се оправи в деня на сватбата. Изберете човек, с когото се чувствате комфортно.</p><blockquote>Съвет от нас: не бързайте. Срещнете се лично с поне 2-3 фотографа, преди да вземете решение. Снимките са това, което ще остане, когато всичко друго отшуми.</blockquote><p>Ако искате да разберете как работим ние в Take Two Studio, свържете се с нас за предварителна консултация. Ще отговорим честно на всички тези 7 въпроса и на всеки друг, който имате.</p>',
            ],
            [
                'title' => 'Сватбен Getting Ready - защо първият час е най-важният за албума',
                'slug' => 'svatben-getting-ready-purvi-chas',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Много двойки подценяват сутрешната подготовка и искат фотографът да пристигне малко преди церемонията. Това е грешка, която струва най-емоционалните кадри в деня.',
                'meta_description' => 'Защо сватбеният Getting Ready е най-важният момент за вашия албум и как да го планирате правилно.',
                'body' => '<p>Попитайте която и да е булка кой е най-любимият й кадър от сватбеното видео. Често отговорът не е първият танц, не церемонията и не тортата, а моментът, в който майка й помага с роклята, а приятелките й се смеят в дъното на кадъра. Това е магията на Getting Ready.</p><h2>Защо сутринта има различна светлина</h2><p>Ако подготовката е сутрин между 9 и 12 часа, в стаята влиза мека, разсеяна естествена светлина. Тя прави кожата да изглежда свежа, очите живи, а детайлите по роклята деликатни. Това е светлината, която професионалните фотографи обожават и която е невъзможно да се пресъздаде по-късно през деня.</p><h2>Емоциите са истински, защото денят още не е започнал</h2><p>В 10 сутринта булката още не е разгласена. Приятелките още не са пили шампанско. Мама още не е видяла момичето си в роклята. Това означава, че всяка емоция, която уловим, е първа, истинска и неповторима. Няма повторения.</p><h3>Кадрите, които не бива да пропускате</h3><ul><li>Роклята, закачена до прозореца</li><li>Обувките, пръстенът и бижутата в композиция</li><li>Мама, която слага воала</li><li>Реакцията на татко, когато види дъщеря си готова</li><li>Моментите с приятелките преди излизане</li><li>Последният поглед в огледалото</li></ul><h2>Колко време всъщност трябва на фотографа</h2><p>Минимум 90 минути на една локация. Ако младоженецът се приготвя на друго място, трябва или втори фотограф, или допълнително време за пътуване между локациите. Всичко под това и започваме да прескачаме кадри. В нашите пакети имаме вариант с един фотограф (най-често избиран) и вариант с двама, в зависимост от организацията на деня.</p><h2>Често срещани грешки</h2><p>Грешка №1: оставяте разхвърляни кутии, чаши и дрехи навсякъде. Съвет: изберете един ъгъл от стаята като "чист", където ще се случват кадрите.</p><p>Грешка №2: прекалено много хора в стаята. Петнайсет души около булката означава, че няма как да я снимаме без 14 други глави в кадъра. Ограничете до най-близките.</p><p>Грешка №3: готовността свършва 10 минути преди тръгване. Ние имаме нужда от 20-30 минути с вас след като сте готови, за детайли и портрети. Планирайте това в таймлайна. В Take Two Studio правим индивидуален таймлайн за всяка сватба точно за да не се случват подобни пропуски.</p><blockquote>Ако можем да дадем само един съвет за целия сватбен ден, той е: не съкращавайте Getting Ready. Дайте му време, дайте му пространство, и ни позволете да го разкажем.</blockquote>',
            ],
            [
                'title' => 'Локации за сватбена фотосесия в и около Варна',
                'slug' => 'lokacii-svatbena-fotosesiya-varna',
                'category_id' => $catId,
                'cover_image' => $cover,
                'excerpt' => 'Варна и регионът предлагат удивително разнообразие от места за сватбена фотосесия. От морски скали до стари каменни улички - ето нашите любими локации и кога да ги посетите.',
                'meta_description' => 'Най-добрите локации за сватбена фотосесия във Варна и региона - морски, градски и природни. Съвети от Take Two Studio.',
                'body' => '<p>Едно от предимствата да се жените във Варна е, че нямате нужда да пътувате далеч за впечатляваща фотосесия. Градът и околностите му предлагат морски пейзажи, стара архитектура, гори, скали и усамотени плажове. Ето локации, в които реално сме работили и които препоръчваме.</p><h2>Морска градина и крайбрежната алея</h2><p>Класика, която работи винаги. В ранния следобед светлината е мека между дърветата, а алеите са красиви. Най-доброто време: 1-2 часа преди залез. Избягвайте почивните дни по пладне, когато е пренаселено.</p><h2>Св. Константин и Елена</h2><p>Паркът и крайбрежието на курорта са сред редовните ни локации. Стари дървета, красива зеленина, близост до морето и спокойствие дори в активния сезон. Идеално за двойки, които искат природа и море на едно място.</p><h2>Аладжа манастир</h2><p>Скални отвеси, пещери и уникална атмосфера. Идеално за двойки, които искат драматични, кинематографични кадри. Минус: затваря по график, така че трябва да планирате предварително.</p><h2>Евксиноград</h2><p>Старата резиденция с прилежащия парк и морския бряг. Необходимо е предварително разрешение, но резултатът е впечатляващ, съчетание на архитектура, вода и зеленина.</p><h2>Болата и северното крайбрежие</h2><p>Един от най-красивите заливи на българското Черноморие, северно от Каварна. Червени скали, изумрудена вода и минимална урбанизация. Ако сте готови за по-дълъг път, резултатът е сред най-драматичните кадри, които можем да направим.</p><h2>Нос Калиакра</h2><p>Червени скали над морето. Драматично и величествено, особено по залез. Подходящо за двойки, които искат "wow" фактор в албума.</p><h2>Шабла и северните плажове</h2><p>За двойки, които искат уединение и безкраен хоризонт без други хора в кадъра. Дълги, празни плажове и най-красиви залези. Изисква цял ден за пътуване и заснемане.</p><h3>Локации в самия град</h3><ul><li>Стара Варна - каменни улички около Катедралата, перфектно за черно-бели кадри</li><li>Римски терми - древна архитектура като